import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
          'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
sales = [12500, 14200, 16800, 15500, 18900, 21000,
         19500, 22400, 24000, 21800, 26500, 31000]

sorted_pairs = sorted(zip(sales, months))
sorted_sales = [p[0] for p in sorted_pairs]
sorted_months = [p[1] for p in sorted_pairs]

plt.figure(figsize=(10, 5))
plt.plot(sorted_months, sorted_sales, marker='o', color='b', linestyle='-', linewidth=2, label='Sorted Monthly Sales')
plt.title('Monthly Sales Trend - Ascending Order (Line Plot)', fontsize=14, fontweight='bold')
plt.xlabel('Month (Sorted by Sales)', fontsize=12)
plt.ylabel('Sales Amount ($)', fontsize=12)
plt.grid(True, linestyle='--', alpha=0.6)
plt.legend()
plt.tight_layout()
plt.savefig('line_plot_sales.png')
plt.show()

plt.figure(figsize=(10, 5))
plt.bar(months, sales, color='skyblue', edgecolor='navy', alpha=0.85)
plt.title('Monthly Sales Comparison - Chronological (Bar Plot)', fontsize=14, fontweight='bold')
plt.xlabel('Month', fontsize=12)
plt.ylabel('Sales Amount ($)', fontsize=12)
plt.grid(axis='y', linestyle='--', alpha=0.6)
plt.tight_layout()
plt.savefig('bar_plot_sales.png')
plt.show()

import matplotlib.pyplot as plt
