import numpy as np
import pandas as pd

np.random.seed(42)
dates = pd.date_range(start='2026-01-01', periods=365)
city_data = {
    'Date': dates,
    'City_A': np.random.normal(22, 5, 365),
    'City_B': np.random.normal(15, 12, 365),
    'City_C': np.random.normal(28, 2, 365)
}
df = pd.DataFrame(city_data)
cities = ['City_A', 'City_B', 'City_C']

mean_temp = df[cities].mean()

std_temp = df[cities].std()

temp_range = df[cities].max() - df[cities].min()
highest_range_city = temp_range.idxmax()

most_consistent_city = std_temp.idxmin()

print("--- Temperature Variability Results ---")
print("Mean Temperatures:\n", mean_temp)
print("\nStandard Deviations:\n", std_temp)
print("\nTemperature Ranges:\n", temp_range)
print(f"\n🏆 City with Highest Temperature Range: {highest_range_city}")
print(f"🎯 City with Most Consistent Temperature: {most_consistent_city}")

