from collections import Counter
import re
import matplotlib.pyplot as plt
import pandas as pd
try:
    df = pd.read_csv('data.csv')
    feedback_column = df['feedback'].dropna().astype(str)
except FileNotFoundError:
    feedback_column = pd.Series([
        "The product is amazing and the service is great!",
        "Terrible experience, the app is slow and buggy.",
        "Really love the design and usability, highly recommended.",
        "Not bad, but could be much better and faster."
    ])
stop_words = {"the", "and", "is", "a", "an", "to", "in", "it", "of", "for", "on", "with", "this", "but"}
all_words = []
for text in feedback_column:
    cleaned = re.sub(r'[^\w\s]', '', text.lower())
    tokens = [word for word in cleaned.split() if word not in stop_words]
    all_words.extend(tokens)
word_counts = Counter(all_words)
try:
    N = int(input("Enter the number of top frequent words to display (N): "))
except:
    N = 5
top_words = word_counts.most_common(N)
print(f"\n--- Top {N} Most Frequent Words ---")
for word, freq in top_words:
    print(f"{word}: {freq}")
words, freqs = zip(*top_words) if top_words else ([], [])
plt.figure(figsize=(8, 4))
plt.bar(words, freqs, color='teal', edgecolor='black', alpha=0.85)
plt.title(f'Top {N} Most Frequent Words in Customer Feedback', fontsize=13, fontweight='bold')
plt.xlabel('Words', fontsize=11)
plt.ylabel('Frequency', fontsize=11)
plt.grid(axis='y', linestyle='--', alpha=0.6)
plt.tight_layout()
plt.show()

