import pandas as pd
import numpy as np
import scipy.stats as stats
import matplotlib.pyplot as plt

data = {
    'age': [23, 23, 27, 27, 39, 41, 47, 49, 50, 52, 54, 54, 56, 57, 58, 58, 60, 61],
    '%fat': [9.5, 26.5, 7.8, 17.8, 31.4, 25.9, 27.4, 27.2, 31.2, 34.6, 42.5, 28.8, 33.4, 30.2, 34.1, 32.9, 41.2, 35.7]
}
df = pd.DataFrame(data)

df_cleaned = df.drop_duplicates()

stats_summary = pd.DataFrame({
    'Mean': df_cleaned.mean(),
    'Median': df_cleaned.median(),
    'Std Dev': df_cleaned.std()
})

print("--- Statistical Summary ---")
print(stats_summary, "\n")

fig, axes = plt.subplots(2, 2, figsize=(12, 10))

df_cleaned.boxplot(column=['age', '%fat'], ax=axes[0, 0])
axes[0, 0].set_title('Boxplots of Age and %Fat', fontsize=12, fontweight='bold')
axes[0, 0].grid(True, linestyle='--', alpha=0.6)

df_scatter = df_cleaned.sort_values(by='age')
axes[0, 1].scatter(df_scatter['age'], df_scatter['%fat'], color='purple', edgecolor='black', s=80, alpha=0.85)
axes[0, 1].set_title('Scatter Plot: Age vs %Fat (Ascending Order)', fontsize=12, fontweight='bold')
axes[0, 1].set_xlabel('Age (Sorted)')
axes[0, 1].set_ylabel('%Fat')
axes[0, 1].grid(True, linestyle='--', alpha=0.6)

stats.probplot(df_cleaned['age'], dist="norm", plot=axes[1, 0])
axes[1, 0].set_title('Q-Q Plot for Age', fontsize=12, fontweight='bold')
axes[1, 0].grid(True, linestyle='--', alpha=0.6)

stats.probplot(df_cleaned['%fat'], dist="norm", plot=axes[1, 1])
axes[1, 1].set_title('Q-Q Plot for %Fat', fontsize=12, fontweight='bold')
axes[1, 1].grid(True, linestyle='--', alpha=0.6)

plt.tight_layout()
