import numpy as np
from scipy import stats

np.random.seed(42)
drug_group = np.random.normal(loc=12.5, scale=3.5, size=50)
placebo_group = np.random.normal(loc=4.2, scale=3.0, size=50)

def calculate_ci(data, confidence=0.95):
    n = len(data)
    mean = np.mean(data)
    se = stats.sem(data)
    margin_of_error = se * stats.t.ppf((1 + confidence) / 2., n - 1)
    return mean, mean - margin_of_error, mean + margin_of_error

drug_mean, drug_lower, drug_upper = calculate_ci(drug_group)
placebo_mean, placebo_lower, placebo_upper = calculate_ci(placebo_group)

print(f"New Drug Group (Mean Reduction): {drug_mean:.2f} mmHg | 95% CI: [{drug_lower:.2f}, {drug_upper:.2f}]")
print(f"Placebo Group (Mean Reduction):  {placebo_mean:.2f} mmHg | 95% CI: [{placebo_lower:.2f}, {placebo_upper:.2f}]")

import numpy as np
from scipy import stats

np.random.seed(42)
design_a = np.random.binomial(1, 0.12, size=1000)
design_b = np.random.binomial(1, 0.16, size=1000)

t_stat, p_value = stats.ttest_ind(design_a, design_b, equal_var=False)

print(f"Conversion Rate - Design A: {np.mean(design_a)*100:.2f}%")
print(f"Conversion Rate - Design B: {np.mean(design_b)*100:.2f}%")
print(f"T-statistic: {t_stat:.4f}, P-value: {p_value:.4f}")

if p_value < 0.05:
    print("Conclusion: There IS a statistically significant difference between Design A and Design B (Reject Null Hypothesis).")
else:
    print("Conclusion: There is NO statistically significant difference between Design A and Design B.")

